import os
import re
import sys
import logging

from taf.rfrl.utilities.general import get_relative_path
from taf.rfrl.utilities.tl_config import (get_configuration, load_moler_configuration_from_tl,
                                          get_testline_configuration_directory_path, get_testline_name)
from taf.rfrl.utilities.robot.general import (get_builtin_value, set_robot_suite_variable, get_suite_tags_variable,
                                              is_dry_run, set_robot_tags)


@load_moler_configuration_from_tl()
def modify_moler_logging_directory(mode='suite'):
    """
    Change moler logs directory to current suite name/test case name - it's dependant on mode parameter

    :param mode:    Could be: 'suite'/'test case' -
    """
    from moler.config import reconfigure_logging_path
    if mode == 'test case':
        _dir_name = get_builtin_value(param_name="TEST NAME")
    else:
        _dir_name = get_builtin_value(param_name="SUITE NAME")
    dir_name = re.sub(r'\s+', '_', _dir_name)
    if mode == 'suite':
        dir_name = dir_name.split(".")[-1]

    log_dir = os.path.join(get_builtin_value(param_name="OUTPUT DIR"), "moler", dir_name)
    reconfigure_logging_path(logging_path=log_dir)


def get_suite_dir():
    """
    Get path to the current suite directory.
    :return: Path to the current suite directory.
    """
    suite_path = get_builtin_value('SUITE_SOURCE')
    return os.path.dirname(suite_path) if os.path.isfile(suite_path) else suite_path


def get_test_results_path():
    """
    Get path to test results directory - based on OUTPUT DIR variable.
    :return: Path to test results directory.
    """
    return get_builtin_value('OUTPUT DIR')


def get_log_path():
    """
    Get path to log directory. If LOG_PATH is not defined, it will set it to test case log path.
    :return: Path to log directory.
    """
    log_path = get_builtin_value('LOG_PATH')
    if log_path is None:
        log_path = set_test_case_log_path()

    return log_path


def get_relative_path_to_test_results(absolute_path):
    """
    Get relative path to test results directory from absolute path.
    :param absolute_path: The absolute path to convert.
    :return: Relative path from test results directory to absolute_path.
    """
    base_path = get_test_results_path()
    return get_relative_path(absolute_path=absolute_path, base_path=base_path)


def set_test_case_log_path(make_dir=True):
    """
    Set log path for the current test case based on OUTPUT_DIR, SUITE NAME and TEST NAME.
    :param make_dir: If True, creates the directory if it does not exist.
    :return: Path to the log directory for the current test case.
    """
    _log_path = os.path.join(f"{get_builtin_value('OUTPUT_DIR')}",
                             f"{get_builtin_value('SUITE NAME')}", f"{get_builtin_value('TEST NAME')}")

    log_path = re.sub(r'\s+', '_', _log_path)
    set_robot_suite_variable(param_name='LOG_PATH', param_value=log_path)

    # needed for SISO test cases from taf.rfrl.procedures
    set_robot_suite_variable(param_name='logs_path', param_value=log_path)

    if make_dir:
        os.makedirs(log_path, exist_ok=True)
    return log_path


def set_test_case_qc_tag(test_instance_id=None):
    """
    Set QC tag for the current test case based on test_instance_id(if provided).
    :param test_instance_id: QC test instance ID to set as tag.
    """
    if test_instance_id is not None:
        set_robot_tags(f'QC_{test_instance_id}')


def get_repository_path():
    def _get_pythonpath():
        for i in range(len(sys.argv)):
            if sys.argv[i] == '--pythonpath':
                if i + 1 < len(sys.argv):
                    return sys.argv[i + 1]
        return None

    repository_path = None

    # /home/ute/Auto5G/.....
    # /home/ute/robotws5g/......
    re_repo = re.compile(r'(?P<REPO_PATH>.*(Auto5G|test_repository|robotws(5g)?)/)')

    match = re_repo.search(get_builtin_value('SUITE SOURCE'))
    if match:
        repository_path = match.group('REPO_PATH')

    if repository_path is None:
        if 'site-packages/gears' in get_builtin_value('SUITE SOURCE'):
            repository_path = _get_pythonpath()
        if repository_path is None and 'gears' in get_builtin_value('SUITE SOURCE'):
            # eg: gears/krakow.vrf/oam/testsuite/
            repository_path = os.getcwd()
    if repository_path is None:
        repository_path = '/home/ute/Auto5G/'

    return repository_path


def get_release_name(bts_id=0, du_id=0):
    """
    Get release name of the software on the BTS.
    :param bts_id: ID of the BTS
    :param du_id: ID of the DU
    :return: Release name of the software. SBTS00 in case of TRUNK.
    """
    from taf.rfrl.bts.devices.du.du_operations import GnbDuOperations
    from taf.rfrl.bts.helpers.sw_versions import SwVersionFactory

    try:
        sw_version = GnbDuOperations().get_bts_sw_version(bts_id=bts_id, du_id=du_id)
    except Exception:
        sw_version = get_builtin_value('ENB_BUILD')

    sw = SwVersionFactory.create_sw_version(sw_version)
    return sw.release


class DefaultFileLocation:
    """
    Class to handle default file locations for commissioning and other configuration files.
    """

    def __init__(self):
        if not is_dry_run():
            self.test_repo_path = get_repository_path()
            self.tl_repo_path = get_testline_configuration_directory_path()

    def get_commissioning_dir(self, location=None, testline_name=None, branch=None):
        """
        Returns path to directory with commissioning files.
        :param location: testline's location
        :param testline_name: name of testline
        :param branch: software branch, if None then it will be read from WebEM or ENB_BUILD variable
                       It could be also a list of branches - then the first existing directory will be returned
        :return: path to commissioning dir
        """
        if branch is None:
            branch = self.get_commissioning_branch()

        if isinstance(branch, list):
            branches = branch
        else:
            branches = [branch]

        if 'SBTS00' in branches and 'TRUNK' not in branches:  # it is temporary - delete when migrate to GEARS
            branches.append('TRUNK')

        logging.debug("[GET_COMMISSIONING_DIR] Searching commissioning directory for branches: {}".format(branches))

        branch_commissioning_dir = self._check_if_commissioning_directories_exists(self.tl_repo_path, branches)
        if branch_commissioning_dir:
            return branch_commissioning_dir

        if location is None and testline_name is None:
            configuration = get_configuration(log_warning=False) or get_configuration()
            if configuration:
                location, testline_name = configuration

        other_dirs_to_check = [
            os.path.join(self.test_repo_path, 'commissionings', location, testline_name),
        ]

        new_dir = os.path.join(self.test_repo_path, 'resources', 'testlines', testline_name)
        if get_builtin_value('GEARSDIR'):
            other_dirs_to_check.insert(0, new_dir)
        else:
            other_dirs_to_check.append(new_dir)

        for tl_commissioning_dir in other_dirs_to_check:
            branch_commissioning_dir = self._check_if_commissioning_directories_exists(tl_commissioning_dir, branches)
            if branch_commissioning_dir:
                return branch_commissioning_dir

    @staticmethod
    def _check_if_commissioning_directories_exists(tl_commissioning_dir, branches):
        logging.debug(f"[GET_COMMISSIONING_DIR] checking SCF in {tl_commissioning_dir}")
        if not os.path.exists(tl_commissioning_dir):
            logging.debug(f"[GET_COMMISSIONING_DIR] Directory does not exist: {tl_commissioning_dir}")
            return False
        logging.debug(f"[GET_COMMISSIONING_DIR] {tl_commissioning_dir} exists")

        number_of_branches = len(branches)
        for index, branch in enumerate(branches, 1):
            check_if_other_sbts_dirs = True if index == number_of_branches else False
            branch_commissioning_dir = os.path.join(tl_commissioning_dir, branch)
            if not os.path.exists(branch_commissioning_dir):
                logging.debug(f"[GET_COMMISSIONING_DIR] Directory does not exist: {branch_commissioning_dir}")
                if check_if_other_sbts_dirs:
                    entries = os.listdir(tl_commissioning_dir)
                    sbts_dirs = [entry for entry in entries if
                                 os.path.isdir(os.path.join(tl_commissioning_dir, entry)) and 'SBTS' in entry]
                    if sbts_dirs:
                        logging.debug(f"[GET_COMMISSIONING_DIR] Wanted branch does not exist - but other "
                                      f"directories are available: {sbts_dirs} under {tl_commissioning_dir}")
                        return branch_commissioning_dir
                    return False
                continue

            logging.info(f"[GET_COMMISSIONING_DIR] Found commissioning directory: {branch_commissioning_dir}")
            return branch_commissioning_dir

    def get_default_scf_name(self, bts_type='GNB', bts_id=0, prefix_tag=None, sub_device=None):
        """
        Returns default SCF file name based on bts_type, bts_id, prefix_tag and sub_device.
        """
        prefix = '{}_'.format(prefix_tag) if prefix_tag else ''
        if sub_device:
            self._validate_sub_device(sub_device)
        sub_device = '_{}'.format(sub_device.upper()) if sub_device else ''
        scf_name = '{}{}{}{}_SCF.xml'.format(prefix, bts_type, bts_id, sub_device)
        return scf_name

    @staticmethod
    def _validate_sub_device(sub_device):
        sub_devices = ['ASIR', 'CU', r'DU\d+']
        validate_results = [re.search(dev, sub_device) for dev in sub_devices]
        if not any(validate_results):
            raise ValueError(
                "Incorrect sub_device name: '{}' - but should be one of {}".format(sub_device, sub_devices))

    def get_swconfig_dir(self):
        """
        Returns path to directory with software configuration files.
        """
        configuration = get_configuration()
        location = configuration[0]
        if location:
            swconfig_dir = os.path.join(self.test_repo_path, 'commissionings', location, 'swconfig')
            return swconfig_dir

    def get_commissioning_branch(self):
        """
        Returns release of software. Release is read from WebEM - if fails then tries to get it from ENB_BUILD variable.
        :return: release of software
        """
        return get_release_name()

    def get_custom_config_yaml_path(self):
        _re_yaml_path = r"(?P<prefix>.*)(?P<config>CONFIGS_(?P<path>[\w|\/|-]+\.(yaml|yml)))(?P<suffix>.*)"
        path = get_builtin_value('SUITE_SOURCE')
        test_tags = get_builtin_value("TEST_TAGS")
        tags = test_tags if test_tags else get_suite_tags_variable(path=path)
        config_tags = [re.search(_re_yaml_path, tag).string for tag in tags if re.search(_re_yaml_path, tag)]
        custom_config_path = ""
        if config_tags:
            custom_config_path = config_tags[0]
        else:
            logging.warning(
                'CONFIGS tags not defined in the testsuite. Please add CONFIGS tag with yaml path as a value,'
                'eg: CONFIGS_Krakow/CLOUD_5G_ASIKR_ABILB4_AEUD/TRUNK/config.yaml'
                ' OR select another SCF selection method')
        custom_config_path = re.search(_re_yaml_path, custom_config_path).group('path')
        custom_config_yaml = os.path.join(self.test_repo_path, 'custom-config', custom_config_path)
        return custom_config_yaml

    @staticmethod
    def get_path_to_default_testline_dir():
        """
        Get path to default testline directory in resources/testlines.
        :return: Path to the default testline directory.
        """
        testlines_dir = os.path.abspath(os.path.join(get_builtin_value('GEARSDIR'), 'resources', 'testlines'))
        return os.path.join(testlines_dir, 'Default')

    @staticmethod
    def get_path_to_default_testline_file(file_name):
        """
        Get path to default testline file.
        :param file_name: Name of the file to find. eg default_swconfig.txt
        :return: Path to the default testline file if found, otherwise None.
        """
        tl_dir = DefaultFileLocation.get_path_to_default_testline_dir()
        return DefaultFileLocation._get_path_to_specific_file(base_dir=tl_dir, file_name=file_name)

    @staticmethod
    def get_path_to_testline_specific_dir(testline_name=None):
        """
        Get path to testline specific directory in resources/testlines.
        :param testline_name: Name of the testline. If None, it will use the current testline name.
        :return: Path to the testline specific directory.
        """
        testlines_dir = os.path.abspath(os.path.join(get_builtin_value('GEARSDIR'), 'resources', 'testlines'))
        testline_name = testline_name or get_testline_name()
        return os.path.join(testlines_dir, testline_name)

    @staticmethod
    def get_path_to_testline_specific_file(file_name, testline_name=None, release=None):
        """
        Get path to testline specific file. It first checks in release specific directory, then in testline directory.
        :param file_name: Name of the file to find.
        :param testline_name: Name of the testline. If None, it will use the current testline name.
        :param release: Release name. If None, it will use the current release name.
        :return: Path to the testline specific file if found, otherwise None.
        """
        tl_dir = DefaultFileLocation.get_path_to_testline_specific_dir(testline_name=testline_name)
        return DefaultFileLocation._get_path_to_specific_file(base_dir=tl_dir, file_name=file_name, release=release)

    @staticmethod
    def get_path_to_feature_testline_specific_dir(testline_name=None):
        """
        Get path to testline specific directory in suite resources/testlines.
        :param testline_name: Name of the testline. If None, it will use the current testline name.
        :return: Path to the feature testline specific directory.
        """
        suite_dir = get_suite_dir()
        testline_name = testline_name or get_testline_name()
        return os.path.join(suite_dir, 'resources', 'testlines', testline_name)

    @staticmethod
    def get_path_to_feature_testline_specific_file(file_name, testline_name=None, release=None):
        tl_feature_dir = DefaultFileLocation.get_path_to_feature_testline_specific_dir(testline_name=testline_name)
        return DefaultFileLocation._get_path_to_specific_file(base_dir=tl_feature_dir, file_name=file_name,
                                                              release=release)

    @staticmethod
    def _get_path_to_specific_file(base_dir, file_name, release=None):
        """
        Get path to testline specific file. It first checks in release specific directory, then in testline directory.
        :param base_dir: Base directory to search in.
        :param file_name: Name of the file to find.
        :param release: Release name. If None, it will use the current release name.
        :return: Path to the specific file if found, otherwise None.
        """
        release = release or get_release_name()
        tl_release_dir = os.path.join(base_dir, release)
        for dir_path in [tl_release_dir, base_dir]:
            file_path = os.path.join(dir_path, file_name)
            if os.path.exists(file_path):
                logging.debug(f"[GET_PATH_TO_SPECIFIC_FILE] File found: {file_path}")
                return file_path
            logging.debug(f"[GET_PATH_TO_SPECIFIC_FILE] File NOT found: {file_path}")
